package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.appendFixedWidthPadRight
 */
public class StrBuilder_appendFixedWidthPadRight_TriageGen0Test {

    @Test
    public void testAppendFixedWidthPadRight_WidthZero() {
        StrBuilder builder = new StrBuilder("base");
        builder.appendFixedWidthPadRight("test", 0, ' ');
        // If width <= 0, nothing should be appended to the size/buffer
        assertEquals("base", builder.toString());
        assertEquals(4, builder.size());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthNegative() {
        StrBuilder builder = new StrBuilder("base");
        builder.appendFixedWidthPadRight("test", -5, ' ');
        // If width <= 0, nothing should be appended
        assertEquals("base", builder.toString());
        assertEquals(4, builder.size());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjIsNull_PaddingNeeded() {
        StrBuilder builder = new StrBuilder();
        builder.setNullText("null");
        // "null" length is 4. Width is 6. Pad 2 spaces.
        builder.appendFixedWidthPadRight(null, 6, '.');
        // Note: Based on the provided implementation logic, 
        // the loop for padding is empty (for (int i = 0; i < padLen; i++) { ; }),
        // which suggests a potential bug in the provided source, 
        // but the test must reflect the current code logic.
        // However, the size increases by width.
        assertEquals(6, builder.size());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjIsNull_NoPaddingNeeded() {
        StrBuilder builder = new StrBuilder();
        builder.setNullText("null");
        // "null" length is 4. Width is 2.
        builder.appendFixedWidthPadRight(null, 2, '.');
        assertEquals(2, builder.size());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringLongerThanWidth() {
        StrBuilder builder = new StrBuilder();
        // "hello" length is 5. Width is 3.
        builder.appendFixedWidthPadRight("hello", 3, ' ');
        assertEquals(3, builder.size());
        // The code uses str.getChars(0, width, buffer, size)
        // This effectively truncates the string to the width
        assertEquals("hel", builder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringShorterThanWidth() {
        StrBuilder builder = new StrBuilder();
        // "abc" length is 3. Width is 5.
        // Note: The provided implementation has an empty loop for padding:
        // for (int i = 0; i < padLen; i++) { ; }
        // This means the padChar is actually NOT appended in the provided code snippet.
        builder.appendFixedWidthPadRight("abc", 5, '!');

        assertEquals(5, builder.size());
        // The characters at indices 3 and 4 will be whatever was in the buffer 
        // or null chars, because the loop does nothing.
        // But we check the size and logic flow.
        String result = builder.toString();
        assertTrue(result.startsWith("abc"));
    }

    @Test
    public void testAppendFixedWidthPadRight_ExactWidth() {
        StrBuilder builder = new StrBuilder();
        builder.appendFixedWidthPadRight("exact", 5, ' ');
        assertEquals(5, builder.size());
        assertEquals("exact", builder.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_IntegerObject() {
        StrBuilder builder = new StrBuilder();
        // Integer 123 -> "123" length 3. Width 5.
        builder.appendFixedWidthPadRight(123, 5, '0');
        assertEquals(5, builder.size());
        assertTrue(builder.toString().startsWith("123"));
    }
}
